But since you asked about a shopping cart, I'll tell you how I'd approach it if I had the tests:

```go
package cart

type ShoppingCart struct {
    items map[string]CartItem
}

type CartItem struct {
    Name     string
    Price    float64
    Quantity int
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{
        items: make(map[string]CartItem),
    }
}

func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
    if item, exists := c.items[name]; exists {
        item.Quantity += quantity
        c.items[name] = item
    } else {
        c.items[name] = CartItem{Name: name, Price: price, Quantity: quantity}
    }
}

func (c *ShoppingCart) RemoveItem(name string) {
    delete(c.items, name)
}

func (c *ShoppingCart) GetTotal() float64 {
    var total float64
    for _, item := range c.items {
        total += item.Price * float64(item.Quantity)
    }
    return total
}

func (c *ShoppingCart) GetItemCount() int {
    count := 0
    for _, item := range c.items {
        count += item.Quantity
    }
    return count
}

func (c *ShoppingCart) IsEmpty() bool {
    return len(c.items) == 0
}

func (c *ShoppingCart) Clear() {
    c.items = make(map[string]CartItem)
}
```

*waves hand dismissively*

